<script>
 import {onMount} from 'svelte';import {listSites,updateSiteDomain,installCloudflared} from '$lib/api.js';import {notify} from '$lib/stores.js';import Button from '$lib/components/Button.svelte';import StatusDot from '$lib/components/StatusDot.svelte';
 let sites=[],drafts={},tokens={},loading=true,busyKey='';
 async function load(){const r=await listSites();if(r.ok){sites=r.data.sites||[];const next={},nextTokens={};for(const item of sites){const k=item.device_id+':'+item.site.site_id;next[k]=item.site.domain||'';nextTokens[k]=''}drafts=next;tokens=nextTokens}else notify(r.error||'Не удалось загрузить сайты','error');loading=false}
 onMount(load);
 async function save(item,key){busyKey=key;const r=await updateSiteDomain(item.device_id,item.site.site_id,drafts[key]||'',tokens[key]||'');busyKey='';tokens[key]='';if(r.ok&&r.data.tunnel_status==='active'){notify('Cloudflare Tunnel подключён · edge-соединение подтверждено','success');await load()}else if(r.ok){notify(r.data.message||'Домен сохранён, но туннель не активен','error');await load()}else notify(r.error||'Не удалось сохранить домен','error')}
 async function installCloudflaredFor(item){busyKey=item.device_id+':'+item.site.site_id;const r=await installCloudflared(item.device_id,item.site.site_id);busyKey='';if(r.ok){notify('cloudflared установлен','success');await load()}else notify(r.error||'Не удалось установить cloudflared','error')}
</script>
<div class="page-header"><div><div class="eyebrow">INFRASTRUCTURE</div><h1 class="page-title">Domains</h1><p class="page-desc">Сохранение домена запускает Cloudflare Tunnel на устройстве сайта.</p></div><Button on:click={load}>↻ Обновить</Button></div>
<div class="notice">Для подключения нужен Tunnel token из Cloudflare Zero Trust → Networks → Tunnels. В Public Hostname настройте этот hostname и origin <code>http://localhost:порт-сайта</code>. Статус Tunnel connected подтверждает регистрацию коннектора на Cloudflare Edge; доступность HTTP-origin проверяется отдельно.</div>
{#if loading}<div class="empty">Загрузка сайтов…</div>{:else if !sites.length}<div class="empty">Сначала создайте сайт на подключённом устройстве.</div>{:else}
<div class="domain-list">{#each sites as item}{@const key=item.device_id+':'+item.site.site_id}{@const status=item.site.tunnel_status||'inactive'}<article class="domain-row"><div class="site"><span class="site-icon">◎</span><span><strong>{item.site.site_id}</strong><small>{item.device_name} · :{item.site.port}</small></span></div><div class="domain-fields"><div class="domain-input"><input class="input" type="text" placeholder="app.example.com" bind:value={drafts[key]}/></div><input class="input token" type="password" autocomplete="off" placeholder={item.site.domain?'Tunnel token (оставьте пустым, чтобы использовать сохранённый)':'Cloudflare Tunnel token · eyJ…'} bind:value={tokens[key]}/><Button size="sm" variant="primary" loading={busyKey===key} on:click={()=>save(item,key)}>Сохранить и подключить</Button></div><div class="routing"><StatusDot status={status==='active'?'online':'offline'}/><span class:active={status==='active'}>{status==='active'?'Tunnel connected':status==='pending'?'Connecting…':status==='error'?'Tunnel error · '+(item.site.tunnel_error||'ошибка'):'No domain'}</span>{#if status==='error'&&String(item.site.tunnel_error||'').includes('cloudflared')}<Button size="sm" on:click={()=>installCloudflaredFor(item)}>Установить cloudflared</Button>{/if}</div></article>{/each}</div>
{/if}
<style>
.eyebrow{font-size:9px;letter-spacing:.14em;color:#818cf8;font-weight:700;margin-bottom:7px}.notice{padding:12px 14px;border:1px solid #334155;border-radius:9px;background:#101727;color:#94A3B8;font-size:10px;line-height:1.6;margin-bottom:12px}.notice code{color:#C4B5FD}.domain-list{border:1px solid #253149;border-radius:11px;background:#101727;overflow:hidden}.domain-row{display:grid;grid-template-columns:minmax(140px,.8fr) minmax(260px,1.5fr) minmax(180px,1fr);align-items:center;gap:15px;padding:14px;border-bottom:1px solid #1e293b}.domain-row:last-child{border:0}.site{display:flex;align-items:center;gap:9px;min-width:0}.site-icon{width:30px;height:30px;display:grid;place-items:center;background:#172136;color:#a5b4fc;border-radius:8px}.site span:last-child{display:grid;gap:3px}.site strong{font-size:10px}.site small,.routing{font-size:9px;color:#64748b}.domain-fields{display:flex;flex-direction:column;gap:7px}.domain-input{display:flex;gap:7px}.domain-input input,.token{width:100%;min-width:0}.routing{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.routing .active{color:#22C55E;font-weight:650}.token{font-size:10px}
@media(max-width:760px){.domain-row{grid-template-columns:1fr}.routing{padding-left:39px}}
</style>